    function __ESBMC_assume(bool) internal pure {}

    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(c).balance > amount);
        require(address(this).balance >= amount);

        uint cBalBefore = address(c).balance;
        uint receiverBalBefore = receiver.balance;

        bool reverted;
        c.multiplicate{value: amount}(receiver); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || address(c).balance == cBalBefore + amount);
    }

    receive() external payable {}
